  'Targets stay where you set them.': 'लक्ष्य वैसे ही रहते हैं जैसे आपने तय किए।',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'हर सेट में सभी रेप्स पूरे करें तो वज़न बढ़ता है। बार-बार चूकने पर डीलोड होता है।',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up — double if you double the reps. One failure resets 10 %.': 'दो सामान्य सेट और आख़िरी सेट फ़ेल्योर तक। उस सेट में लक्ष्य पार करें तो वज़न बढ़ता है — रेप्स दोगुने करें तो दोगुना। एक बार चूकने पर 10 % घट जाता है।',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'एक ही वज़न पर रेप रेंज में ऊपर बढ़ें। हर सेट में रेंज का ऊपरी सिरा छुएँ तो वज़न बढ़ता है और रेप्स नीचे लौट आते हैं।',
  'Hold every set for the full duration and the target goes up.': 'हर सेट पूरे समय तक होल्ड करें तो लक्ष्य बढ़ जाता है।',
  'Nothing logged yet — this session sets the baseline.': 'अभी कुछ दर्ज नहीं — यह सेशन आधार तय करेगा।',
  'Held every set for the full time — target up by {0}s.': 'हर सेट पूरे समय तक होल्ड किया — लक्ष्य {0} सेकंड बढ़ा।',
  'Short {0} sessions in a row — back off to {1}s and build up again.': 'लगातार {0} सेशन कम रहे — {1} सेकंड पर लौटें और फिर से बढ़ाएँ।',
  'Last time came up short — same target again.': 'पिछली बार पूरा नहीं हुआ — वही लक्ष्य दोबारा।',
  'Top of the rep range in every set — {0} {1} more, back to {2} reps.': 'हर सेट में रेंज का ऊपरी सिरा — {0} {1} ज़्यादा, वापस {2} रेप्स पर।',
  'Stalled {0} sessions — deload to {1} {2}.': '{0} सेशन से रुकावट — {1} {2} पर डीलोड।',
  'Same weight — aim for {0} reps this time.': 'वही वज़न — इस बार {0} रेप्स का लक्ष्य रखें।',
  'Last set hit {0} reps — twice the target, so take a double jump of {1} {2}.': 'आख़िरी सेट में {0} रेप्स — लक्ष्य से दोगुने, इसलिए {1} {2} की दोगुनी छलांग।',
  'Every rep last time — {0} {1} more.': 'पिछली बार सारे रेप्स — {0} {1} ज़्यादा।',
  'Missed reps {0} sessions running — reset to {1} {2} and work back up.': 'लगातार {0} सेशन रेप्स चूके — {1} {2} पर लौटें और फिर से बढ़ाएँ।',
  'Missed reps — reset to {0} {1} and work back up.': 'रेप्स चूके — {0} {1} पर लौटें और फिर से बढ़ाएँ।',
  'Missed reps last time — same weight again ({0} of {1} to go).': 'पिछली बार रेप्स चूके — वही वज़न दोबारा ({1} में से {0} बाकी)।',
  'Bodyweight — every rep last time, so go for {0} this time.': 'बॉडीवेट — पिछली बार सारे रेप्स, तो इस बार {0} का लक्ष्य रखें।',
  'Bodyweight — same target again until every set is clean.': 'बॉडीवेट — जब तक हर सेट साफ़ न हो, वही लक्ष्य।',

