  'After how many workouts': 'कितने वर्कआउट के बाद',
  'An AI coach that can build your plan and adjust it from what you log. Off until you turn it on.': 'एक AI कोच जो आपका प्लान बनाता है और आपके रिकॉर्ड के हिसाब से उसे ढालता है। जब तक आप चालू न करें, बंद रहता है।',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs on this server, it never changes anything without your say-so, and it is off until you turn it on.': 'एक AI कोच जो आपका प्लान बनाता है और आपके दर्ज किए गए रिकॉर्ड के हिसाब से उसे ढालता है। यह इसी सर्वर पर चलता है, आपकी सहमति के बिना कुछ नहीं बदलता, और जब तक आप चालू न करें बंद रहता है।',
  'Any pending suggestion is discarded and scheduled reviews stop. Your Coach history stays, and you can turn it back on anytime.': 'लंबित सुझाव हट जाते हैं और निर्धारित समीक्षाएँ रुक जाती हैं। आपका इतिहास रहता है और आप कभी भी दोबारा चालू कर सकते हैं।',
  'Anything else?': 'और कुछ?',
  'Anything it should know? (optional) — e.g. “right shoulder pinches on overhead work”': 'कुछ बताना चाहेंगे? (वैकल्पिक) — जैसे “ओवरहेड मूवमेंट में दायें कंधे में खिंचाव होता है”',
  'Anything to work around?': 'कुछ ध्यान रखने योग्य?',
  'Anything worth remembering? (optional)': 'कुछ याद रखने लायक? (वैकल्पिक)',
