  'Your plan goes back to how it was before you accepted them. Workouts you have logged since are untouched.': 'आपका प्लान उसी स्थिति में लौट जाएगा जैसा स्वीकार करने से पहले था। उसके बाद दर्ज वर्कआउट अछूते रहेंगे।',
