  'Only while today’s step goal isn’t met yet.': 'केवल तब तक जब तक आज का कदम लक्ष्य पूरा न हो।',
  'Reminds you at this time on days that have a routine planned and not yet trained — with your step goal in the same notification.': 'जिन दिनों रूटीन प्लान है और अभी ट्रेनिंग नहीं हुई, उन दिनों इस समय याद दिलाता है — उसी सूचना में आपके कदम लक्ष्य के साथ।',
  'Counting with your phone’s step sensor.': 'फ़ोन के स्टेप सेंसर से गिनती हो रही है।',
  'Counting with the motion sensor — keep MAHDI-JYM open and on screen.': 'मोशन सेंसर से गिनती हो रही है — MAHDI-JYM को खुला और स्क्रीन पर रखें।',
