  'Uses your phone’s built-in step sensor — light on battery.': 'फ़ोन के बिल्ट-इन स्टेप सेंसर का उपयोग करता है — बैटरी पर हल्का।',
  'Counts steps with your phone’s motion sensor while this page is open.': 'यह पेज खुला रहने तक फ़ोन के मोशन सेंसर से कदम गिनता है।',
