  'Android keeps counting in its step sensor while the app sleeps; the steps arrive the next time MAHDI-JYM reads it. On iPhone, today’s total is filled in from the motion history.': 'ऐप के सोते समय Android अपने स्टेप सेंसर में गिनती जारी रखता है; अगली बार MAHDI-JYM पढ़ने पर कदम आ जाते हैं। iPhone पर आज का कुल मोशन इतिहास से भरा जाता है।',
  'Browsers only deliver motion data while the page is open and on screen. For all-day counting, install the Android app.': 'ब्राउज़र मोशन डेटा तभी देते हैं जब पेज खुला और स्क्रीन पर हो। पूरे दिन की गिनती के लिए Android ऐप इंस्टॉल करें।',
  'Stride length': 'कदम की लंबाई',
