  'In the browser, reminders appear while MAHDI-JYM is open. Install the Android app for reminders with the app closed.': 'ब्राउज़र में रिमाइंडर तभी दिखते हैं जब MAHDI-JYM खुला हो। ऐप बंद होने पर रिमाइंडर के लिए Android ऐप इंस्टॉल करें।',
