  'Not allowed': 'अनुमति नहीं',
  'When a goal is reached with the app closed, Android shows the celebration over the lock screen. To see it on top of other apps too, allow “Display over other apps”.': 'ऐप बंद होने पर लक्ष्य पूरा होने पर Android लॉक स्क्रीन पर जश्न दिखाता है। दूसरे ऐप्स के ऊपर भी देखने के लिए “दूसरे ऐप्स के ऊपर दिखाएँ” की अनुमति दें।',
  'Full screen, with confetti and a fanfare, at every 1,000 steps and at your goal.': 'पूर्ण स्क्रीन, कंफ़ेटी और धुन के साथ, हर 1,000 कदम पर और लक्ष्य पर।',
