  'Google sign-in isn’t set up for this version of the app yet. Your data stays on this phone for now.': 'इस ऐप संस्करण के लिए Google साइन-इन अभी सेट नहीं है। फ़िलहाल आपका डेटा इसी फ़ोन पर रहेगा।',
  'No connection to Google. Check the internet and try again.': 'Google से कोई कनेक्शन नहीं। इंटरनेट जाँचें और फिर कोशिश करें।',
  'Google Drive access wasn’t allowed, so nothing can be saved to the account.': 'Google Drive की अनुमति नहीं दी गई, इसलिए खाते में कुछ सेव नहीं हो सकता।',
  'Google Play services aren’t available on this phone.': 'इस फ़ोन पर Google Play सेवाएँ उपलब्ध नहीं हैं।',
  'Google sign-in didn’t work. Try again, or keep your data on this phone.': 'Google साइन-इन नहीं हो सका। फिर कोशिश करें, या अपना डेटा इसी फ़ोन पर रखें।',
  'Keep your progress safe': 'अपनी प्रगति सुरक्षित रखें',
  'Sign in with a Google account that’s already on this phone — no password — and every workout, step, glass of water and setting is saved to it. Or keep everything on this phone.': 'इस फ़ोन पर पहले से मौजूद Google खाते से साइन इन करें — बिना पासवर्ड — और हर वर्कआउट, हर कदम, हर गिलास पानी और हर सेटिंग उसमें सेव होगी। या सब कुछ इसी फ़ोन पर रखें।',
