  'Put routines on days in Plan — each one gets its reminder.': 'प्लान में दिनों पर रूटीन रखें — हर एक को उसका रिमाइंडर मिलेगा।',
  'For every day — or set a time per day below': 'हर दिन के लिए — या नीचे हर दिन का समय तय करें',
  'Reminds you on days that have a routine planned and not yet trained — with the exercises, about how long it takes and your step goal in the same notification.': 'उन दिनों याद दिलाता है जब रूटीन तय है और अभी ट्रेनिंग नहीं हुई — उसी सूचना में व्यायाम, लगभग समय और आपका कदम लक्ष्य।',
  '{0} ml per 1,000 steps after the first {1}, and {2} ml per minute of training. Updates through the day — also in the notification.': 'पहले {1} के बाद हर 1,000 कदम पर {0} ml, और ट्रेनिंग के हर मिनट पर {2} ml। दिन भर अपडेट होता है — सूचना में भी।',
  'Automatic goal': 'ऑटो लक्ष्य',
  'From your body weight, today’s steps and workouts': 'आपके वज़न, आज के कदमों और वर्कआउट से',
  'Tap a glass, cup, can or bottle in the notification to add it, Undo to take the last one back, Edit to open this screen — all with the app closed.': 'सूचना में गिलास, कप, कैन या बोतल पर टैप करके जोड़ें, आख़िरी हटाने के लिए पूर्ववत करें, यह स्क्रीन खोलने के लिए संपादित करें — ऐप बंद रहते हुए।',
  'Water panel in the notifications': 'सूचनाओं में पानी पैनल',
