  // 2.7.0 — back button, one notification, sign-in
  'This is taking longer than usual. Check the internet, or cancel and try again.': 'इसमें सामान्य से ज़्यादा समय लग रहा है। इंटरनेट जाँचें, या रद्द करके फिर कोशिश करें।',
