  // 2.8 — Google account without setup (Android Backup)
  'Welcome back — your data was restored from your Google account': 'वापसी पर स्वागत है — आपका डेटा आपके Google खाते से वापस आ गया',
  'Google Drive isn’t set up for this version of the app yet — your data is still saved to your Google account through Android Backup.': 'Google Drive इस ऐप संस्करण के लिए अभी सेट नहीं है — फिर भी आपका डेटा Android बैकअप से आपके Google खाते में सहेजा जाता है।',
  'Saved privately to your Google account — only MAHDI-JYM can read it. Sign out anytime in Settings.': 'आपके Google खाते में निजी रूप से सहेजा गया — इसे केवल MAHDI-JYM पढ़ सकता है। सेटिंग्स में कभी भी साइन आउट करें।',
  'Everything is saved to your Google account automatically through Android Backup, and comes back when you install MAHDI-JYM again.': 'सब कुछ Android बैकअप से अपने आप आपके Google खाते में सहेजा जाता है, और MAHDI-JYM दोबारा इंस्टॉल करने पर वापस आ जाता है।',
  'Now saved to Google Drive': 'अब Google Drive में सहेजा जा रहा है',
  'Your data stays on this phone. Changes are no longer saved to your Google account.': 'आपका डेटा इसी फ़ोन पर रहेगा। बदलाव अब आपके Google खाते में सहेजे नहीं जाएँगे।',
  'Sign in with a Google account that’s already on this phone — no password. Everything is then saved to that account automatically.': 'इस फ़ोन पर पहले से मौजूद Google खाते से साइन इन करें — बिना पासवर्ड। फिर सब कुछ अपने आप उसी खाते में सहेजा जाता है।',
  'Workouts, plan, steps, water, body weight and settings are saved through Android Backup to your Google account. Android uploads it in the background, usually within a few hours, and puts it back when you install MAHDI-JYM again or on a new phone. Progress photos stay on this phone.': 'वर्कआउट, प्लान, कदम, पानी, शरीर का वज़न और सेटिंग्स Android बैकअप से आपके Google खाते में सहेजे जाते हैं। Android इन्हें बैकग्राउंड में अपलोड करता है, आमतौर पर कुछ घंटों में, और MAHDI-JYM दोबारा या नए फ़ोन पर इंस्टॉल करने पर वापस लाता है। प्रगति की तस्वीरें इसी फ़ोन पर रहती हैं।',
  'Google Drive': 'Google Drive',
  'Android Backup': 'Android बैकअप',
