  "Fill half your plate with vegetables.": "अपनी आधी थाली सब्ज़ियों से भरें।",
  "Eat slowly: it takes about 20 minutes to feel full.": "धीरे खाएँ: पेट भरने का एहसास लगभग 20 मिनट में आता है।",
