  "A 500 kcal daily deficit, high protein, and a week of home workouts, HIIT and walking.": "रोज़ 500 kcal की कमी, ज़्यादा प्रोटीन, और घर पर वर्कआउट, HIIT और पैदल चलने का एक हफ़्ता।",
  "A bit short": "थोड़ी कम",
  "A notification at each time, even when the app is closed": "हर समय पर एक सूचना, ऐप बंद होने पर भी",
  "A personal log, not a diagnosis. Ranges follow the American Heart Association and the American Diabetes Association. Talk to your doctor about your numbers and before changing any medicine.": "यह निजी लॉग है, निदान नहीं। सीमाएँ अमेरिकन हार्ट एसोसिएशन और अमेरिकन डायबिटीज़ एसोसिएशन के अनुसार हैं। अपने आँकड़ों के बारे में और कोई दवा बदलने से पहले डॉक्टर से बात करें।",
  "A small surplus is enough: about 250–300 kcal over what you burn.": "थोड़ा अधिशेष काफ़ी है: जितना जलाते हैं उससे लगभग 250–300 kcal ज़्यादा।",
  "About {0} minutes — your gym session is waiting.": "लगभग {0} मिनट — आपका जिम सेशन इंतज़ार कर रहा है।",
