  "Add": "जोड़ें",
  "Add a little weight or one more rep than last time: that is how muscle grows.": "पिछली बार से थोड़ा ज़्यादा वज़न या एक रेप ज़्यादा: मांसपेशी ऐसे ही बढ़ती है।",
  "Add a medicine or vitamin": "दवा या विटामिन जोड़ें",
  "Add a name and at least one time.": "एक नाम और कम से कम एक समय जोड़ें।",
  "Add reading": "रीडिंग जोड़ें",
  "Add your medicines and vitamins to tick them off and get a reminder at each time.": "अपनी दवाएँ और विटामिन जोड़ें ताकि उन्हें टिक कर सकें और हर समय पर याद दिलाया जाए।",
  "Add your neck{0} below for the more accurate US-Navy tape method.": "ज़्यादा सटीक US-Navy टेप विधि के लिए नीचे अपनी गर्दन{0} जोड़ें।",
  "Add your wrist to find your frame, or pick it yourself.": "अपनी कद-काठी जानने के लिए कलाई जोड़ें, या ख़ुद चुनें।",
  "Adjusted +{0} kcal because you are losing too fast.": "+{0} kcal बदला गया क्योंकि आप बहुत तेज़ी से घटा रहे हैं।",
