  "Google Drive isn’t switched on for this app yet": "इस ऐप के लिए Google Drive अभी चालू नहीं है",
  "That needs a one-time setup in Google Cloud by the app’s owner. Until then everything is saved through Android Backup — nothing is lost.": "इसके लिए ऐप के मालिक को Google Cloud में एक बार सेटअप करना होगा। तब तक सब कुछ Android Backup से सहेजा जाता है — कुछ नहीं खोता।",
  "How to switch on Google Drive": "Google Drive कैसे चालू करें",
