  "Sign in with Google in Settings": "सेटिंग में Google से साइन इन करें",
  "Automatic versions": "स्वचालित संस्करण",
  "Once a day, when something changed, a full copy is kept on this phone and in Google Drive. The newest ones are kept; older ones are removed.": "दिन में एक बार, कुछ बदलने पर, पूरी कॉपी इस फ़ोन और Google Drive में रखी जाती है। नई कॉपियाँ रहती हैं, पुरानी हट जाती हैं।",
  "Once a day, when something changed, a full copy is kept on this phone. The newest ones are kept; older ones are removed.": "दिन में एक बार, कुछ बदलने पर, पूरी कॉपी इस फ़ोन पर रखी जाती है। नई कॉपियाँ रहती हैं, पुरानी हट जाती हैं।",
  "Save a version every day": "हर दिन एक संस्करण सहेजें",
