  "Save a version now": "अभी एक संस्करण सहेजें",
  "On this phone": "इस फ़ोन पर",
  "No versions yet — the first one is saved today.": "अभी कोई संस्करण नहीं — पहला आज सहेजा जाएगा।",
  "In Google Drive": "Google Drive में",
  "Refresh": "रीफ़्रेश करें",
  "Loading…": "लोड हो रहा है…",
  "Could not reach Google Drive — check the connection.": "Google Drive तक नहीं पहुँच सके — कनेक्शन जाँचें।",
  "No versions in Drive yet.": "Drive में अभी कोई संस्करण नहीं।",
  "A version is a full copy: workouts, plan, routines, steps, water, body weight, health log and settings. Progress photos stay where they are. For a copy you can keep anywhere, use Export in Settings.": "संस्करण एक पूरी कॉपी है: वर्कआउट, प्लान, रूटीन, कदम, पानी, वज़न, हेल्थ लॉग और सेटिंग। प्रगति की फ़ोटो जहाँ हैं वहीं रहती हैं। कहीं भी रखने लायक कॉपी के लिए सेटिंग में एक्सपोर्ट इस्तेमाल करें।",
  "Open console.cloud.google.com with your Google account and create a project (any name).": "अपने Google खाते से console.cloud.google.com खोलें और एक प्रोजेक्ट बनाएँ (कोई भी नाम)।",
  "APIs & Services → Library → search “Google Drive API” → Enable.": "APIs & Services → Library → “Google Drive API” खोजें → Enable.",
  "OAuth consent screen → External → fill in the app name and your email → add the scope …/auth/drive.appdata → add your own account as a test user.": "OAuth consent screen → External → ऐप का नाम और अपना ईमेल भरें → स्कोप …/auth/drive.appdata जोड़ें → अपना खाता टेस्ट यूज़र के रूप में जोड़ें।",
  "Credentials → Create credentials → OAuth client ID → Android → paste the package name and SHA-1 below.": "Credentials → Create credentials → OAuth client ID → Android → नीचे दिया पैकेज नाम और SHA-1 चिपकाएँ।",
  "Wait about 5 minutes, then come back here and tap Try again. Nothing changes in the app itself.": "लगभग 5 मिनट रुकें, फिर यहाँ लौटकर “फिर से कोशिश करें” दबाएँ। ऐप में कुछ नहीं बदलता।",
  "Switch on Google Drive": "Google Drive चालू करें",
  "Only needed once, by the app’s owner. Saving through Android Backup keeps working the whole time.": "केवल एक बार, ऐप के मालिक द्वारा। Android Backup से सहेजना पूरे समय चलता रहता है।",
  "Package name": "पैकेज नाम",
