  // 4.1 — Google check, today’s workout linked to the scale
  "The Google Drive API is switched off in the Cloud project": "Cloud प्रोजेक्ट में Google Drive API बंद है",
  "In Google Cloud: APIs & Services → Library → Google Drive API → Enable. Then test again in a few minutes.": "Google Cloud में: APIs & Services → Library → Google Drive API → Enable. फिर कुछ मिनट बाद दोबारा जाँचें।",
  "Google doesn’t know this app yet": "Google अभी इस ऐप को नहीं पहचानता",
  "Create an Android OAuth client in Google Cloud with exactly the package name and SHA-1 shown here. Wait about 5 minutes, then test again.": "Google Cloud में ठीक यहाँ दिखाए गए पैकेज नाम और SHA-1 के साथ Android OAuth क्लाइंट बनाएँ। लगभग 5 मिनट रुकें, फिर दोबारा जाँचें।",
  "Access to Google Drive wasn’t allowed": "Google Drive तक पहुँच की अनुमति नहीं दी गई",
  "Tap Test Google Drive and choose Allow. While the app is in testing, your account must be listed as a test user on the OAuth consent screen.": "“Google Drive जाँचें” दबाएँ और Allow चुनें। जब तक ऐप टेस्टिंग में है, आपका खाता OAuth सहमति स्क्रीन पर टेस्ट यूज़र के रूप में जुड़ा होना चाहिए।",
  "Google refused access for this account": "Google ने इस खाते के लिए पहुँच अस्वीकार कर दी",
  "On the OAuth consent screen: user type External, your account added as a test user, and the scope …/auth/drive.appdata added. Then test again.": "OAuth सहमति स्क्रीन पर: यूज़र टाइप External, आपका खाता टेस्ट यूज़र के रूप में और स्कोप …/auth/drive.appdata जोड़ें। फिर दोबारा जाँचें।",
  "No connection to Google": "Google से कनेक्शन नहीं है",
  "Check the internet connection and try again.": "इंटरनेट कनेक्शन जाँचें और फिर कोशिश करें।",
  "Not signed in": "साइन इन नहीं है",
  "Sign in with your Google account in Settings.": "सेटिंग्स में अपने Google खाते से साइन इन करें।",
