  "Your data stays on this phone and in your Google Drive. Changes are no longer saved to your Google account or to the Drive file.": "आपका डेटा इस फ़ोन और आपके Google Drive में रहता है। बदलाव अब Google खाते या Drive फ़ाइल में सहेजे नहीं जाएँगे।",
  "Every change is written to your file a moment after you make it. Sign in with Google as well to also keep a copy through Android Backup.": "हर बदलाव कुछ ही पलों में आपकी फ़ाइल में लिखा जाता है। Android Backup से भी कॉपी रखने के लिए Google से साइन इन करें।",
