  "Press the dough into thin discs, fill one, cover it with another and seal the edges.": "आटे की पतली गोल परतें बनाएँ, एक पर भरावन रखें, दूसरी से ढकें और किनारे बंद करें।",
  "Cook in gently boiling water for {0}, until they float.": "हल्के उबलते पानी में {0} पकाएँ, जब तक ऊपर न तैरें।",
  "Drop the kubba into the simmering soup and cook for 15 minutes.": "कुब्बा को उबलते शोरबे में डालकर 15 मिनट पकाएँ।",
  "Fry in a little oil until golden on both sides — or bake to save calories.": "थोड़े तेल में दोनों तरफ़ सुनहरा होने तक तलें — या कैलोरी बचाने के लिए बेक करें।",
  "Split the fish along the back, open it flat and season with salt and turmeric.": "मछली को पीठ से चीरकर फैलाएँ और नमक-हल्दी लगाएँ।",
  "Mash until thick and smooth, then stir in the tomato paste and spices.": "गाढ़ा और चिकना होने तक मसलें, फिर टमाटर पेस्ट और मसाले मिलाएँ।",
  "Beat with a wooden spoon until smooth and stretchy.": "लकड़ी के चम्मच से चिकना और लचीला होने तक फेंटें।",
  "Serve hot in a bowl with some of the cooking broth.": "थोड़े शोरबे के साथ कटोरे में गर्म परोसें।",
