  "Arrange everything yourself — school, meals, drinks, work, prayer — on the days you choose, with an end time and your own notes.": "सब कुछ खुद व्यवस्थित करें — स्कूल, भोजन, पेय, काम, नमाज़ — चुने हुए दिनों पर, खत्म होने के समय और अपने नोट्स के साथ।",
  "School Sunday to Thursday, 7:30 to 12:40, then lunch, rest, homework, work, drinks and dinner — and a calmer weekend.": "रविवार से गुरुवार स्कूल, 7:30 से 12:40, फिर लंच, आराम, होमवर्क, काम, पेय और डिनर — और आरामदेह सप्ताहांत।",
  "Each reminder shows the time, your notes and the food and drinks you chose with their calories — with Done ✓ and In 10 min.": "हर रिमाइंडर में समय, आपके नोट्स और चुने हुए खाने-पेय की कैलोरी दिखती है — “हो गया ✓” और “10 मिनट में” के साथ।",
  "Colas, lemon-lime, fruit sodas, malt and energy drinks and homemade mojitos — in cans, bottles and glasses of every size, with sugar in teaspoons.": "कोला, लेमन-लाइम, फ्रूट सोडा, माल्ट और एनर्जी ड्रिंक, घर का मोहितो — हर साइज़ के कैन, बोतल और गिलास में, चीनी चम्मच में।",
  "Pistachios, almonds, walnuts, cashews, the seeds you crack and kerzat — raw, roasted or salted, by the handful, with what each is good for.": "पिस्ता, बादाम, अखरोट, काजू, तोड़कर खाए जाने वाले बीज और केरज़ात — कच्चे, भुने या नमकीन, मुट्ठी भर, हर एक के फ़ायदे के साथ।",
  "All notifications in one place": "सभी सूचनाएँ एक जगह",
  "Which reminders are on, what still rings today, and the phone’s notification settings grouped by kind.": "कौन-से रिमाइंडर चालू हैं, आज क्या बजना बाकी है, और फ़ोन की सूचना सेटिंग प्रकार के अनुसार।",
  "Smoother everywhere": "हर जगह और स्मूद",
  "Tidier tools, smoother animations and many small fixes — drinks are now logged to the right meal.": "ज़्यादा व्यवस्थित टूल, स्मूद एनिमेशन और कई छोटे सुधार — अब पेय सही भोजन में दर्ज होते हैं।",
