  "Regular colas are high in sugar and have some caffeine. The zero versions have no calories.": "सामान्य कोला में चीनी ज़्यादा और थोड़ा कैफ़ीन होता है। ज़ीरो वाले में कैलोरी नहीं होती।",
  "Lemon & lime": "नींबू और लाइम",
  "No caffeine, but just as sweet as cola — the diet versions have no sugar.": "कैफ़ीन नहीं, पर कोला जितनी ही मीठी — डाइट वाले में चीनी नहीं।",
  "Fruit sodas": "फ्रूट सोडा",
  "Coloured and sweet, usually with no real fruit. Sparkling water with fresh juice is a lighter choice.": "रंगीन और मीठी, अक्सर असली फल के बिना। ताज़े जूस वाला सोडा पानी हल्का विकल्प है।",
  "Soda & sparkling water": "सोडा और स्पार्कलिंग पानी",
  "Soda and sparkling water have no calories. Tonic water and ginger ale are sweetened.": "सोडा और स्पार्कलिंग पानी में कैलोरी नहीं होती। टॉनिक वॉटर और जिंजर एल मीठे होते हैं।",
  "Malt drinks 0.0%": "माल्ट ड्रिंक 0.0%",
  "Malt drinks have no alcohol. The flavoured ones are as sweet as soft drinks; the classic is lighter.": "माल्ट ड्रिंक में अल्कोहल नहीं होता। फ्लेवर वाले सॉफ्ट ड्रिंक जितने मीठे हैं; क्लासिक हल्का है।",
  "Energy drinks": "एनर्जी ड्रिंक",
  "Lots of caffeine and sugar. Not for children, pregnancy or anyone sensitive to caffeine — one can a day at most.": "बहुत कैफ़ीन और चीनी। बच्चों, गर्भावस्था या कैफ़ीन के प्रति संवेदनशील लोगों के लिए नहीं — दिन में ज़्यादा से ज़्यादा एक कैन।",
  "Homemade sodas": "घर के बने सोडा",
  "Made at home with soda water, fresh lemon and mint — you decide how sweet. Values assume a little sugar.": "घर पर सोडा पानी, ताज़े नींबू और पुदीने से बने — मिठास आप तय करें। मान थोड़ी चीनी मानकर हैं।",
  "High in caffeine — not for children, pregnancy or anyone sensitive to caffeine. Never mix it with alcohol, and not during hard exercise in the heat.": "ज़्यादा कैफ़ीन — बच्चों, गर्भावस्था या कैफ़ीन के प्रति संवेदनशील लोगों के लिए नहीं। इसे कभी शराब के साथ न मिलाएँ, और गर्मी में कड़ी कसरत के दौरान न पिएँ।",
  "No sugar: sweetened with sweeteners, so almost no calories.": "चीनी नहीं: स्वीटनर से मीठा, इसलिए लगभग कोई कैलोरी नहीं।",
