  "Up at 7:00, school Sunday to Thursday 7:30–12:40 — then lunch, a nap, homework, games, review, sport, dinner and a light snack before bed at 22:00. Friday and Saturday: study, family, football and rest.": "7:00 बजे उठना, रविवार से गुरुवार 7:30–12:40 स्कूल — फिर लंच, झपकी, होमवर्क, गेम, रिविज़न, खेल, डिनर और 22:00 बजे सोने से पहले हल्का नाश्ता। शुक्रवार और शनिवार: पढ़ाई, परिवार, फ़ुटबॉल और आराम।",
