  "Up at 7:00, school 7:30–12:40, then lunch, a nap, homework, games, review, sport, dinner and bed at 22:00 — Friday and Saturday too. Your current blocks are replaced; reminders stay as they are.": "7:00 बजे उठना, 7:30–12:40 स्कूल, फिर लंच, झपकी, होमवर्क, गेम, रिविज़न, खेल, डिनर और 22:00 बजे सोना — शुक्रवार और शनिवार भी। अभी के हिस्से बदल जाएँगे; रिमाइंडर जैसे हैं वैसे रहेंगे।",
  "Update": "अपडेट करें",
