  "A milky morning tea — breakfast in many Iraqi homes.": "सुबह की दूध वाली चाय — कई इराक़ी घरों का नाश्ता।",
  "Tea with a squeeze of lemon — light after a heavy meal.": "नींबू की कुछ बूँदों वाली चाय — भारी खाने के बाद हल्की।",
  "Tea with fresh mint from the garden, after lunch.": "दोपहर के खाने के बाद, बग़ीचे के ताज़ा पुदीने वाली चाय।",
  "Hot cocoa on cold Baghdad winter evenings.": "बग़दाद की ठंडी सर्दियों की शामों में गर्म कोको।",
  "Warm milk sweetened with date syrup — a winter comfort.": "खजूर के सिरप से मीठा किया गुनगुना दूध — सर्दियों का सुकून।",
  "Small and strong, sipped slowly after a meal or with guests.": "छोटी और कड़क, खाने के बाद या मेहमानों के साथ धीरे-धीरे।",
  "The quick coffee of students and late-night studying.": "छात्रों और देर रात की पढ़ाई की झटपट कॉफ़ी।",
  "Squeezed fresh at home on long, hot summer afternoons.": "गर्मियों की लंबी, गर्म दोपहरों में घर पर ताज़ा निचोड़ा जाता है।",
  "Sweet and sour — a Ramadan favourite poured cold at iftar.": "खट्टा-मीठा — रमज़ान में इफ़्तार पर ठंडा परोसा जाने वाला पसंदीदा।",
  "Oranges from the orchards of Diyala, squeezed at the juice shop.": "दियाला के बाग़ों के संतरे, जूस की दुकान पर निचोड़े हुए।",
  "Freshly pressed carrots — sold in every Iraqi juice shop.": "ताज़ा निचोड़ी गाजर — हर इराक़ी जूस की दुकान पर।",
  "Fresh apples blended at the juice shop.": "जूस की दुकान पर पीसे गए ताज़ा सेब।",
  "Made from the sweet grapes of Iraqi summers.": "इराक़ी गर्मियों के मीठे अंगूरों से बना।",
  "Thick mango juice, a favourite at Basra’s juice stands.": "गाढ़ा आम का जूस, बसरा के जूस ठेलों का पसंदीदा।",
  "The juice shop’s best seller — banana and cold milk.": "जूस की दुकान का सबसे ज़्यादा बिकने वाला — केला और ठंडा दूध।",
  "A pink favourite when strawberries are in season.": "स्ट्रॉबेरी के मौसम का गुलाबी पसंदीदा।",
  "Layers of fruit, milk and nuts — the famous Iraqi juice-shop cocktail.": "फलों, दूध और मेवों की परतें — इराक़ी जूस दुकानों का मशहूर कॉकटेल।",
  "Instant coffee": "इंस्टेंट कॉफ़ी",
  "Iraqi breakfast plate (eggs, cheese, bread & tea)": "इराक़ी नाश्ता (अंडे, पनीर, रोटी और चाय)",
  "Two boiled eggs with samoon": "सामून के साथ दो उबले अंडे",
  "Two fried eggs with bread": "रोटी के साथ दो तले अंडे",
  "Cheese, olives and bread (light dinner)": "पनीर, ज़ैतून और रोटी (हल्का डिनर)",
  "Rice with white bean stew (timman w fasolia)": "सफ़ेद बीन्स की करी के साथ चावल (तिम्मन व फ़ासोलिया)",
  "Rice with okra stew (timman w bamia)": "भिंडी की करी के साथ चावल (तिम्मन व बामिया)",
  "Green bean stew (fasolia khadra)": "हरी बीन्स की करी (फ़ासोलिया ख़द्रा)",
  "Sheikh mahshi (stuffed eggplant)": "शेख़ महशी (भरवाँ बैंगन)",
  "Baked pasta with béchamel (makarona)": "बेशमेल वाला बेक्ड पास्ता (मकरोना)",
